// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 n1, uint256 n2) public {
        vm.assume(t > 1 && t < type(uint256).max - 1);
        vm.assume(n1 % 15 != 0 && n2 % 15 != 0 && n2 != n1);

        vm.warp(t);
        vm.roll(n1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // Immediately after the call at t, pastBlockTime == t + 1, so a call
        // at t + 1 violates block.timestamp > pastBlockTime and must revert.
        vm.warp(t + 1);
        vm.roll(n2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "call at t+1 must revert");
    }
}
